CREATE OR REPLACE FUNCTION nexus.gc_expire_quarantine(
    dim                      int,
    p_tenant_id              text,
    p_quarantine_collection  text,
    p_origin_collection      text,
    p_cutoff                 text,
    p_floor_fraction         float8,
    p_floor_min_chunks       int,
    p_force                  boolean
)
RETURNS TABLE(expired bigint, refused bigint)
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
    v_mine      bigint;
    v_chashes   bytea[];
    v_protected bytea[];
    v_expired   bigint;
    v_refused   bigint;
    v_frac      float8;
BEGIN
    IF dim NOT IN (384, 768, 1024) THEN
        RAISE EXCEPTION
            'gc_expire_quarantine: unsupported dim %. Supported values: 384, 768, 1024',
            dim;
    END IF;

    IF dim = 384 THEN
        SELECT count(*),
               array_agg(chash) FILTER (
                   WHERE COALESCE(metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff
                     AND NOT EXISTS (
                           SELECT 1 FROM nexus.catalog_document_chunks m
                            WHERE m.tenant_id  = chunks_384.tenant_id
                              AND m.collection = p_origin_collection
                              AND m.chash      = chunks_384.chash
                         )),
               array_agg(chash) FILTER (
                   WHERE COALESCE(metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff
                     AND EXISTS (
                           SELECT 1 FROM nexus.catalog_document_chunks m
                            WHERE m.tenant_id  = chunks_384.tenant_id
                              AND m.collection = p_origin_collection
                              AND m.chash      = chunks_384.chash
                         ))
          INTO v_mine, v_chashes, v_protected
          FROM nexus.chunks_384
         WHERE tenant_id  = p_tenant_id
           AND collection = p_quarantine_collection
           AND COALESCE(metadata->>'origin_collection', p_origin_collection) = p_origin_collection;

        v_expired := COALESCE(array_length(v_chashes, 1), 0);
        v_refused := COALESCE(array_length(v_protected, 1), 0);

        IF v_expired = 0 THEN
            RETURN QUERY SELECT 0::bigint, v_refused;
            RETURN;
        END IF;

        v_frac := v_expired::float8 / v_mine::float8;
        IF v_expired >= p_floor_min_chunks AND v_frac > p_floor_fraction AND NOT p_force THEN
            RETURN QUERY SELECT 0::bigint, v_expired + v_refused;
            RETURN;
        END IF;

        DELETE FROM nexus.chunks_384
         WHERE tenant_id = p_tenant_id AND collection = p_quarantine_collection
           AND chash = ANY(v_chashes);

        RETURN QUERY SELECT v_expired, v_refused;
        RETURN;

    ELSIF dim = 768 THEN
        SELECT count(*),
               array_agg(chash) FILTER (
                   WHERE COALESCE(metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff
                     AND NOT EXISTS (
                           SELECT 1 FROM nexus.catalog_document_chunks m
                            WHERE m.tenant_id  = chunks_768.tenant_id
                              AND m.collection = p_origin_collection
                              AND m.chash      = chunks_768.chash
                         )),
               array_agg(chash) FILTER (
                   WHERE COALESCE(metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff
                     AND EXISTS (
                           SELECT 1 FROM nexus.catalog_document_chunks m
                            WHERE m.tenant_id  = chunks_768.tenant_id
                              AND m.collection = p_origin_collection
                              AND m.chash      = chunks_768.chash
                         ))
          INTO v_mine, v_chashes, v_protected
          FROM nexus.chunks_768
         WHERE tenant_id  = p_tenant_id
           AND collection = p_quarantine_collection
           AND COALESCE(metadata->>'origin_collection', p_origin_collection) = p_origin_collection;

        v_expired := COALESCE(array_length(v_chashes, 1), 0);
        v_refused := COALESCE(array_length(v_protected, 1), 0);

        IF v_expired = 0 THEN
            RETURN QUERY SELECT 0::bigint, v_refused;
            RETURN;
        END IF;

        v_frac := v_expired::float8 / v_mine::float8;
        IF v_expired >= p_floor_min_chunks AND v_frac > p_floor_fraction AND NOT p_force THEN
            RETURN QUERY SELECT 0::bigint, v_expired + v_refused;
            RETURN;
        END IF;

        DELETE FROM nexus.chunks_768
         WHERE tenant_id = p_tenant_id AND collection = p_quarantine_collection
           AND chash = ANY(v_chashes);

        RETURN QUERY SELECT v_expired, v_refused;
        RETURN;

    ELSIF dim = 1024 THEN
        SELECT count(*),
               array_agg(chash) FILTER (
                   WHERE COALESCE(metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff
                     AND NOT EXISTS (
                           SELECT 1 FROM nexus.catalog_document_chunks m
                            WHERE m.tenant_id  = chunks_1024.tenant_id
                              AND m.collection = p_origin_collection
                              AND m.chash      = chunks_1024.chash
                         )),
               array_agg(chash) FILTER (
                   WHERE COALESCE(metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff
                     AND EXISTS (
                           SELECT 1 FROM nexus.catalog_document_chunks m
                            WHERE m.tenant_id  = chunks_1024.tenant_id
                              AND m.collection = p_origin_collection
                              AND m.chash      = chunks_1024.chash
                         ))
          INTO v_mine, v_chashes, v_protected
          FROM nexus.chunks_1024
         WHERE tenant_id  = p_tenant_id
           AND collection = p_quarantine_collection
           AND COALESCE(metadata->>'origin_collection', p_origin_collection) = p_origin_collection;

        v_expired := COALESCE(array_length(v_chashes, 1), 0);
        v_refused := COALESCE(array_length(v_protected, 1), 0);

        IF v_expired = 0 THEN
            RETURN QUERY SELECT 0::bigint, v_refused;
            RETURN;
        END IF;

        v_frac := v_expired::float8 / v_mine::float8;
        IF v_expired >= p_floor_min_chunks AND v_frac > p_floor_fraction AND NOT p_force THEN
            RETURN QUERY SELECT 0::bigint, v_expired + v_refused;
            RETURN;
        END IF;

        DELETE FROM nexus.chunks_1024
         WHERE tenant_id = p_tenant_id AND collection = p_quarantine_collection
           AND chash = ANY(v_chashes);

        RETURN QUERY SELECT v_expired, v_refused;
        RETURN;
    END IF;
END;
$$

